<?php
namespace Database\Seeders; use Illuminate\Database\Seeder; use Illuminate\Support\Facades\DB;
class RolePermissionSeeder extends Seeder { public function run():void { $codes=['dashboard.view'=>'Melihat dashboard','siswa.view'=>'Melihat data siswa','siswa.update.request'=>'Mengajukan perubahan data siswa','siswa.update.approve'=>'Menyetujui perubahan data siswa','ppdb.verify'=>'Memverifikasi pendaftaran PPDB','akademik.manage'=>'Mengelola data akademik','user.manage'=>'Mengelola pengguna','audit.view'=>'Melihat audit trail','loginlog.view'=>'Melihat log login']; foreach($codes as $code=>$label) DB::table('hak_akses')->updateOrInsert(['kode_hak_akses'=>$code],['nama_hak_akses'=>$label]); foreach(['siswa','guru','tu','kepsek'] as $role) DB::table('role')->updateOrInsert(['nama_role'=>$role],['deskripsi'=>$role]); } }
